sys_script_fix.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    g_form.clearValue('request');
    g_form.clearValue('request_type_v1');
    g_form.clearValue('request_type');

    var entity = g_form.getReference('entity_id', fetchRegion);
    //Type appropriate comment here, and begin script below
}

function fetchRegion(entity) {
    var region = entity.getDisplayValue('u_region');
    if (region == 'NAM') {
        g_form.setDisplay('roc', true);
        g_form.setMandatory('request_type', false);
        g_form.setDisplay('request_type', false);
        g_form.setMandatory('request_type_v1', true);
        g_form.setDisplay('request_type_v1', true);



    } else {

        g_form.setDisplay('roc', false);
        g_form.setMandatory('request_type', true);
        g_form.setDisplay('request_type', true);
        g_form.setMandatory('request_type_v1', false);
        g_form.setDisplay('request_type_v1', false);




    }

}
